  [["Как студент, я хочу записывать расходы, чтобы понимать траты"], ["Как админ, я хочу видеть логи, чтобы искать ошибки"], (["Как гость, я хочу войти, чтобы работать"], True), (["Как мама, я хочу напоминания, чтобы не забывать"], True)],
  [("def parse_story(text):\n    role, rest = text.split(\", я хочу \")\n    action, goal = rest.split(\", чтобы \")\n    return {\"role\": role, \"action\": action, \"goal\": goal}\n", "В роли остаётся слово «Как»."),
   ("def parse_story(text):\n    start = text.removeprefix(\"Как \")\n    role, rest = start.split(\", я хочу \")\n    action, goal = rest.split(\", чтобы \")\n    return {\"role\": role, \"action\": goal, \"goal\": action}\n", "Действие и цель перепутаны.")],
  hints("История состоит из трёх частей, разделённых запятыми.", "Сначала уберите слово «Как» в начале.", "Роль — до фразы «я хочу».", "Действие — между «я хочу» и «чтобы».", "Цель — после «чтобы»."),
