  "mvp", "def mvp(features):\n    must = [f for f in features if f[\"priority\"] == \"must\"]\n    must.sort(key=lambda f: f[\"hours\"])\n    return [f[\"name\"] for f in must]\n",
  [[[{"name": "A", "priority": "must", "hours": 5}, {"name": "B", "priority": "could", "hours": 1}, {"name": "C", "priority": "must", "hours": 2}]], [[]], ([[{"name": "X", "priority": "must", "hours": 3}, {"name": "Y", "priority": "must", "hours": 3}]], True), ([[{"name": "Z", "priority": "should", "hours": 1}]], True), ([[{"name": "P", "priority": "must", "hours": 9}, {"name": "Q", "priority": "must", "hours": 1}, {"name": "R", "priority": "must", "hours": 5}]], True)],
